# 1. Extract original vertices
original_vertices = sorted({
    vertex
    for facet in original_facets
    for vertex in facet
})

print("Original vertices:", original_vertices)

# 2. Find every vertex Sage created in the subdivision
subdivision_vertices = {
    vertex
    for edge in subdivision
    for vertex in edge
}

# 3. Anything with length > 1 represents a newly-created
# barycentric subdivision vertex
new_vertices = sorted(
    vertex
    for vertex in subdivision_vertices
    if len(vertex) > 1
)

# 4. Start numbering after the largest original vertex
next_id = max(original_vertices) + 1

new_vertex_mapping = {
    vertex: next_id + i
    for i, vertex in enumerate(new_vertices)
}

print("New vertex mapping:")
for vertex, new_id in new_vertex_mapping.items():
    print(f"{vertex} -> {new_id}")


# 5. Convert a Sage barycentric vertex into an integer
def convert_vertex(vertex):
    # Singleton tuple = original vertex
    if len(vertex) == 1:
        return vertex[0]

    # Multi-element tuple = new barycentric vertex
    return new_vertex_mapping[vertex]


# 6. Convert the entire subdivision
converted_subdivision = {
    tuple(convert_vertex(vertex) for vertex in edge)
    for edge in subdivision
}

print("Converted subdivision:")
print(converted_subdivision)